func TestBucketKeepsPoolNonDeletable(t *testing.T) {
	h := Handler()
	createPool(t, h, bucketPool)
	createBucket(t, h, `{"id":"b1","poolId":"bp"}`)

	// Even an empty bucket blocks pool deletion.
